window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n2_p3']={"lk":{"mondai":[{"sec":"moji","no":1,"type":"kanji_reading","instr":"＿＿＿の言葉の読み方として最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"新しい制度の[[導入]]には時間がかかる。","options":["とうにゅう","どうにゅう","どうにゅ","どにゅう"],"explain":"導入 is read どうにゅう (introduction, adoption).","answer":1},{"q":"彼は部下の失敗を強く[[責めた]]りしない。","options":["せめた","ほめた","とめた","しめた"],"explain":"責める is read せめる (to blame).","answer":0},{"q":"少子化により、生徒数が年々[[減少]]している。","options":["げんしょ","けんしょう","かんしょう","げんしょう"],"explain":"減少 is read げんしょう (decrease), with a long しょう.","answer":3},{"q":"{契約|けいやく}の内容について、もう一度[[詳しく]]説明してほしい。","options":["くやしく","こまかく","くわしく","けわしく"],"explain":"詳しい is read くわしい (detailed). こまかく (細かく) means fine/small and is a different word.","answer":2},{"q":"市は高齢者の[[雇用]]を進める方針だ。","options":["こうよう","こよう","こよ","ごよう"],"explain":"雇用 is read こよう (employment).","answer":1}]},{"sec":"moji","no":2,"type":"orthography","instr":"＿＿＿の言葉を漢字で書くとき、最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"新入社員の[[きょういく]]は人事部が担当している。","options":["教育","教養","共育","協育"],"explain":"きょういく (education, training) is written 教育.","answer":0},{"q":"この仕事は期限までに[[しあげる]]必要がある。","options":["試上げる","仕挙げる","仕上げる","支上げる"],"explain":"しあげる (to finish off) is written 仕上げる.","answer":2},{"q":"原料の値上がりで、会社の業績が[[あっか]]している。","options":["悪加","圧化","悪価","悪化"],"explain":"あっか (deterioration) is written 悪化.","answer":3},{"q":"家庭の[[ふたん]]を減らすため、給食費が無料になった。","options":["負胆","付担","負担","負坦"],"explain":"ふたん (burden) is written 負担.","answer":2},{"q":"社会の変化に[[そなえて]]、新しい技術を学んでおく。","options":["供えて","備えて","添えて","構えて"],"explain":"そなえる meaning 'to prepare for' is written 備える. 供える means to offer (at an altar).","answer":1}]},{"sec":"moji","no":3,"type":"word_formation","instr":"（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"この計画は費用の面から見て（　　）現実的だ。","options":["無","不","未","非"],"explain":"非現実的 = unrealistic. 非 attaches to 〜的 words.","answer":3},{"q":"資料がまだ（　　）完成なので、会議を延期した。","options":["未","不","無","非"],"explain":"未完成 = not yet completed.","answer":0},{"q":"大学への進学（　　）は年々上がっている。","options":["割","比","率","度"],"explain":"進学率 = rate of students going on to higher education.","answer":2},{"q":"当社では、年齢ではなく成果（　　）で社員を評価している。","options":["制","{主義|しゅぎ}","性","論"],"explain":"成果主義 = a results-based (performance-based) system.","answer":1},{"q":"書類に誤りがあったので、（　　）{提出|ていしゅつ}を求められた。","options":["再","改","重","復"],"explain":"再提出 = resubmission.","answer":0}]},{"sec":"moji","no":4,"type":"context","instr":"（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"新製品の売れ行きが予想を大きく（　　）、生産が追いつかない。","options":["乗り越え","追い越し","引き上げ","上回り"],"explain":"予想を上回る = to exceed expectations.","answer":3},{"q":"彼女は入社して三年で、チームをまとめる（　　）に選ばれた。","options":["パートナー","リーダー","スポンサー","ライバル"],"explain":"The person who leads (まとめる) a team is the リーダー.","answer":1},{"q":"面接では{緊張|きんちょう}して、言いたいことの半分も言えなかった。本当に（　　）。","options":["くやしい","まぶしい","なつかしい","そうぞうしい"],"explain":"くやしい = frustrating / vexing — the feeling after failing to do your best.","answer":0},{"q":"今回の失敗の原因を（　　）{分析|ぶんせき}し、次に生かしたい。","options":["一方的に","感情的に","{徹底的|てっていてき}に","一時的に"],"explain":"徹底的に分析する = to analyse thoroughly.","answer":2},{"q":"駅前の再開発に対して、住民から反対の声が（　　）。","options":["起きた","出した","立った","上がった"],"explain":"The set phrase is 声が上がる (voices are raised).","answer":3},{"q":"課長は細かいことにうるさいが、仕事の進め方は（　　）合理的だ。","options":["せめて","かえって","いっそ","きわめて"],"explain":"きわめて = extremely. The others do not modify an adjective this way.","answer":3},{"q":"担当者が急に辞めたため、業務の（　　）が十分にできなかった。","options":["取り消し","引き{継|つ}ぎ","打ち合わせ","申し込み"],"explain":"業務の引き継ぎ = handing over duties to a successor.","answer":1}]},{"sec":"moji","no":5,"type":"paraphrase","instr":"＿＿＿の言葉に意味が最も近いものを、１・２・３・４から一つ選びなさい。","items":[{"q":"今日の会議は[[あっけなく]]終わった。","options":["予定より遅く","{激|はげ}しい議論の末に","思ったより簡単に","{誰|だれ}も来ないまま"],"explain":"あっけなく = surprisingly quickly/easily, with less than expected.","answer":2},{"q":"彼の説明は[[あいまい]]だった。","options":["はっきりしなかった","長すぎた","間違っていた","{丁寧|ていねい}だった"],"explain":"あいまい = vague, unclear.","answer":0},{"q":"社長の[[意向]]を確認してから返事します。","options":["考え","予定","指示","経歴"],"explain":"意向 = intention, what someone thinks should be done — closest to 考え. 指示 (instructions) is a trap.","answer":0},{"q":"この{企画|きかく}は[[たちまち]]評判になった。","options":["ようやく","次第に","すぐに","意外にも"],"explain":"たちまち = instantly, in no time.","answer":2},{"q":"{先輩|せんぱい}に仕事の[[コツ]]を教えてもらった。","options":["大変さ","目的","最初の手順","うまくやる方法"],"explain":"コツ = the knack, the trick to doing something well.","answer":3}]},{"sec":"moji","no":6,"type":"usage","instr":"次の言葉の使い方として最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"word":"手際","q":"手際","options":["手際が悪い天気が続いて、洗濯物が乾かない。","彼女は手際よく会議の準備を済ませた。","この道の手際を右に曲がると、駅に出る。","新しい手際を買ったので、料理が楽しくなった。"],"explain":"手際 = skill/efficiency in handling a task; 手際よく = deftly, efficiently.","answer":1},{"word":"発足","q":"発足","options":["電車は定刻どおりに駅を発足した。","朝早く家を発足して、山に登った。","台所から火事が発足し、近所に広がった。","環境問題を考える新しい委員会が来月発足する。"],"explain":"発足 = the launch/establishment of an organisation. Trains 発車, people 出発, fires 発生.","answer":3},{"word":"打ち明ける","q":"打ち明ける","options":["{誰|だれ}にも言えなかった悩みを、思い切って親友に打ち明けた。","部屋が暑かったので、窓を打ち明けて空気を入れかえた。","新製品の発売日を、会社のホームページで打ち明けた。","夜が打ち明けて、空がだんだん明るくなってきた。"],"explain":"打ち明ける = to confide a secret or private feeling to someone. A public announcement is 発表する.","answer":0},{"word":"見合わせる","q":"見合わせる","options":["二人は駅の改札で見合わせて、映画館へ向かった。","大雪のため、本日の運転を見合わせております。","彼は上司の期待に見合わせて、毎晩遅くまで働いた。","新しいスーツに見合わせて、ネクタイも買った。"],"explain":"見合わせる = to postpone / suspend for now (e.g. train service). Meeting up is 待ち合わせる; matching is 合わせる / 見合う.","answer":1},{"word":"{頑丈|がんじょう}","q":"{頑丈|がんじょう}","options":["彼は{頑丈|がんじょう}な性格で、一度決めたことは絶対に変えない。","試験に合格するために、毎日{頑丈|がんじょう}に勉強した。","この机は{頑丈|がんじょう}にできているので、子供が乗っても{壊|こわ}れない。","社長の{頑丈|がんじょう}な判断のおかげで、会社は危機を乗り越えた。"],"explain":"頑丈 = sturdy, solidly built (objects, bodies). A stubborn character is 頑固.","answer":2}]},{"sec":"bunpo","no":7,"type":"grammar_form","instr":"次の文の（　　）に入れるのに最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"市立病院の移転（　　）、市議会で{激|はげ}しい議論が続いている。","options":["にこたえて","に先立って","にとって","をめぐって"],"explain":"〜をめぐって = over / concerning (a disputed matter).","answer":3},{"q":"社長の{挨拶|あいさつ}を（　　）、各部署の代表による発表が続いた。","options":["皮切りに","通じて","中心に","込めて"],"explain":"〜を皮切りに = starting with X, (a series) followed.","answer":0},{"q":"この仕事は経験の有無（　　）、{誰|だれ}でも応募できます。","options":["に限って","に基づいて","を問わず","に{沿|そ}って"],"explain":"〜を問わず = regardless of.","answer":2},{"q":"一度引き受けた（　　）、最後まで責任を持ってやるべきだ。","options":["ところで","以上","くせに","反面"],"explain":"〜以上(は) = now that / since (so one must).","answer":1},{"q":"あの店は駅前に開店した（　　）、客が集まらず、半年で閉店してしまった。","options":["ばかりに","うえは","ものの","からには"],"explain":"〜ものの = although (X happened, the expected result did not follow).","answer":2},{"q":"何度も話し合った（　　）、結局その計画は中止になった。","options":["一方","とたんに","かわりに","あげく"],"explain":"〜たあげく = after (much effort), in the end (a disappointing result).","answer":3},{"q":"部長が戻り（　　）、会議を始めます。","options":["ながら","次第","つつ","がてら"],"explain":"Verb ます-stem + 次第 = as soon as.","answer":1},{"q":"田中さんの話を聞く（　　）、この計画にはまだ問題がありそうだ。","options":["かぎり","あまり","ばかりか","ことなく"],"explain":"〜かぎり = as far as (I can judge from) hearing.","answer":0},{"q":"上司に相談もせずに一人で決めてしまうなんて、勝手（　　）。","options":["でしかない","ではいられない","に越したことはない","にもほどがある"],"explain":"〜にもほどがある = X goes too far / there is a limit to X.","answer":3},{"q":"働き方が変わる（　　）、求められる能力も変わってきた。","options":["うえに","につれて","ばかりに","くせに"],"explain":"〜につれて = as X changes, Y changes too.","answer":1},{"q":"明日の説明会には、取引先の社長も（　　）予定です。","options":["参る","拝見する","お見えになる","お越しする"],"explain":"お見えになる is the honorific for 来る, used for the client's president. 参る is humble; お越しする is not a correct form.","answer":2},{"q":"実際に使ってみ（　　）、このソフトの良さはわからないと思う。","options":["ないことには","ないばかりに","ないうちに","ないまでも"],"explain":"〜ないことには = unless you (do X), you can't (Y).","answer":0}]},{"sec":"bunpo","no":8,"type":"ordering","instr":"次の文の　★　に入る最もよいものを、１・２・３・４から一つ選びなさい。","items":[{"q":"田中さんは ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ {誰|だれ}よりも早く出社している。","options":["休まず","以来","一日も","入社して"],"answer":2,"order":[3,1,2,0],"explain":"入社して以来 (ever since joining) + 一日も休まず (without missing a single day). Correct order: 入社して / 以来 / 一日も / 休まず."},{"q":"計画が ＿＿＿ ＿★＿ ＿＿＿ ＿＿＿ 原因を調べる必要がある。","options":["のか","いかなかった","なぜ","うまく"],"answer":3,"order":[2,3,1,0],"explain":"なぜうまくいかなかったのか = why it did not go well; the embedded question ends in のか. Correct order: なぜ / うまく / いかなかった / のか."},{"q":"この問題は、 ＿＿＿ ＿＿＿ ＿＿＿ ＿★＿ できないだろう。","options":["解決","簡単には","でさえ","専門家"],"answer":0,"order":[3,2,1,0],"explain":"専門家でさえ (even experts) 簡単には解決できない (cannot easily solve). Correct order: 専門家 / でさえ / 簡単には / 解決."},{"q":"彼女が会社を辞めたのは、 ＿＿＿ ＿＿＿ ＿★＿ ＿＿＿ ではないかと思う。","options":["から","いた","悩んで","人間関係に"],"answer":1,"order":[3,2,1,0],"explain":"人間関係に悩んでいたから(ではないか) = (I think it's) because she was troubled by relationships at work. Correct order: 人間関係に / 悩んで / いた / から."},{"q":"現代の社会 ＿＿＿ ＿★＿ ＿＿＿ ＿＿＿ はますます高まっている。","options":["重要性","話す能力の","外国語を","において"],"answer":2,"order":[3,2,1,0],"explain":"において (in) / 外国語を話す能力の重要性 (the importance of the ability to speak foreign languages). Correct order: において / 外国語を / 話す能力の / 重要性."}]},{"sec":"bunpo","no":9,"type":"text_grammar","instr":"次の文章を読んで、文章全体の内容を考えて、５０から５４の中に入る最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"以下は、留学生が書いた作文である。\n\n日本の職場で学んだこと\n\n　私は去年から、ある日本の会社でインターンシップをしている。初めて職場に行った日、一番{驚|おどろ}いたのは「報告・連絡・相談」が非常に大切にされていることだった。私の国では、仕事は任された人が一人で最後までやるのが普通で、途中で上司に何度も相談する人は、あまりいない。能力がないと思われる（５０）。\n　そのため、最初のうちは、困ったことがあっても自分で何とかしようとしていた。（５１）、ある日、私が一人で判断して進めた作業に大きなミスが見つかり、チーム全体の予定が遅れてしまった。そのとき{先輩|せんぱい}に「もっと早く言ってくれれば、すぐに直せたのに」と言われた。\n　この経験を（５２）、私は考え方を変えた。相談するのは弱さではなく、チームで仕事をするための大切な手段なのだ。小さなことでも早めに共有すれば、問題が大きくなる前に対応できる。\n　もちろん、何でも人に聞けばいいというわけではない。自分で調べられることは調べてから相談する（５３）。{先輩|せんぱい}たちを見ていても、質問の前に必ず資料を確認している。\n　来年、国に帰ったら、この経験を（５４）。","questions":[{"q":"50","options":["ことになっているからだ","わけがないからだ","ほかないからだ","おそれがあるからだ"],"explain":"〜おそれがある = there is a risk of (being thought incapable) — the reason people don't consult.","answer":3},{"q":"51","options":["そのうえ","ところが","したがって","つまり"],"explain":"ところが introduces an unexpected turn: despite trying alone, a big mistake happened.","answer":1},{"q":"52","options":["きっかけに","よそに","抜きにして","限りに"],"explain":"〜をきっかけに = taking (this experience) as the trigger, I changed my thinking.","answer":0},{"q":"53","options":["はずがない","べきだろう","わけにはいかない","ものではない"],"explain":"The writer gives advice: you should look things up yourself first — べきだろう.","answer":1},{"q":"54","options":["{同僚|どうりょう}たちにも伝えてもらったものだ","{同僚|どうりょう}たちにも伝えたことにしている","{同僚|どうりょう}たちにも伝えさせてしまった","{同僚|どうりょう}たちにも伝えていきたいと思う"],"explain":"The essay ends with a future hope: 伝えていきたいと思う.","answer":3}]}]},{"sec":"dokkai","no":10,"type":"short","instr":"次の（１）から（５）の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"（１）\n以下は、ある会社の社内メールである。\n\n社員各位\n\n来月{実施|じっし}予定の新入社員研修について、お知らせします。\n当初、研修は本社の会議室で三日間行う予定でしたが、参加者が増えたため、会場を駅前の研修センターに変更します。日程に変更はありません。\nまた、昨年度の参加者アンケートで「実習の時間が足りない」という意見が多かったことを受け、二日目の午後の{講義|こうぎ}を実習に変えることにしました。講師を担当する方は、今月二十日までに実習用の資料を人事部に{提出|ていしゅつ}してください。\n\n人事部　{佐藤|さとう}","questions":[{"q":"このメールで、講師を担当する人がしなければならないことは何か。","options":["二十日までに実習用の資料を人事部に出すこと","研修センターを予約すること","アンケートの結果をもとに{講義|こうぎ}の資料を直すこと","研修の日程を参加者に知らせること"],"explain":"The last sentence asks instructors to submit practical-session materials to HR by the 20th. The venue change is done by HR; the schedule is unchanged.","answer":0}]},{"text":"（２）\n「人に教えることは、二度学ぶことだ」という言葉がある。学生時代、私は{塾|じゅく}で中学生に数学を教えていた。自分では分かっているつもりの問題でも、いざ説明しようとすると、言葉に詰まることがよくあった。分かっていたのは解き方の手順だけで、なぜそうなるのかを理解していなかったのだ。どう説明すれば生徒に伝わるかを考えるうちに、私自身の理解も深まっていった。実は、教える側が一番得をしているのかもしれない。","questions":[{"q":"筆者が最も言いたいことは何か。","options":["数学では、解き方の手順を覚えることが一番大切だ。","中学生に数学を教えるのは、思ったより簡単だ。","人に教えることで、教える人自身の理解も深まる。","人に教える前に、まず自分が完全に理解しなければならない。"],"explain":"The point is that by working out how to explain, the teacher's own understanding deepened — the teacher benefits most.","answer":2}]},{"text":"（３）\n私の住む町では、最近、小さなトラックで食料品を売りに来る「移動販売」をよく見かけるようになった。近くのスーパーが閉店し、車を運転しない高齢者が買い物に困るようになったためだ。トラックが来ると住民が自然に集まり、品物を選びながら会話を楽しんでいる。一人暮らしのお年寄りにとっては、買い物の場であると同時に、人と話す{貴重|きちょう}な機会にもなっているようだ。いつも来る人が{姿|すがた}を見せないと、販売員が家まで様子を見に行くこともあるという。","questions":[{"q":"筆者によると、移動販売は一人暮らしのお年寄りにとってどのようなものになっているか。","options":["買い物ができるだけでなく、人と交流できる場","スーパーより安く品物が買える場","車の運転をしなくてもすむように送ってもらえる場","新しいスーパーを作るために意見を言う場"],"explain":"It is both a place to shop and a valuable chance to talk with people (買い物の場であると同時に、人と話す貴重な機会).","answer":0}]},{"text":"（４）\n在宅勤務が広がり、通勤の負担が減ったと喜ぶ人は多い。しかし、管理職として私が気になっているのは、若い社員の成長である。職場にいれば、{先輩|せんぱい}が電話でどのように話しているか、困ったときにどう判断しているかを、自然に見て学ぶことができる。こうした「見て覚える」機会は、画面越しではなかなか得られない。在宅勤務をやめるべきだとは思わないが、若手が{先輩|せんぱい}と同じ場所で働く日を、意識して設ける必要があるのではないだろうか。","questions":[{"q":"筆者の考えに合うのはどれか。","options":["在宅勤務はやめて、全員が毎日出社するべきだ。","若手社員は、分からないことを画面越しに質問するべきだ。","若手社員が{先輩|せんぱい}の仕事ぶりを近くで見られる日を作るべきだ。","通勤の負担を減らすことを、何よりも優先するべきだ。"],"explain":"The writer does not want to end remote work but wants days set aside when juniors work alongside seniors.","answer":2}]},{"text":"（５）\n以下は、ある会社が取引先に送った文書である。\n\nお取引先各位\n\n{平素|へいそ}より格別のお引き立てを{賜|たまわ}り、{誠|まこと}にありがとうございます。\nさて、{弊社|へいしゃ}では原材料費および物流費の上昇が続いております。これまで経費の{削減|さくげん}に努め、価格を{維持|いじ}してまいりましたが、今後も同じ価格で製品をご{提供|ていきょう}することが困難な状況となりました。\nつきましては、{誠|まこと}に勝手ながら、来年四月一日のご注文分より、一部製品の価格を改定させていただきます。対象製品と新価格につきましては、別紙をご確認ください。\nなお、三月末日までにいただいたご注文につきましては、現行価格にて承ります。","questions":[{"q":"この文書で最も伝えたいことは何か。","options":["三月末までに必ず注文をしなければならないこと","原材料費が上がった理由","別紙にある製品の販売をやめること","四月一日の注文から、一部の製品の値段が上がること"],"explain":"The main message is the price revision (価格を改定) from orders on April 1. Ordering by March is possible but not required.","answer":3}]}]},{"sec":"dokkai","no":11,"type":"mid","instr":"次の（１）から（３）の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"（１）\n　近年、大学では「キャリア教育」と呼ばれる授業が増えている。{履歴書|りれきしょ}の書き方や面接の練習、{企業|きぎょう}で働く人を招いての講演など、内容はさまざまだ。学生からは「{就職活動|しゅうしょくかつどう}に役立つ」と好評で、こうした授業に力を入れている大学ほど、受験生にも人気があるという。\n　しかし、私はこの流れに少し疑問を感じている。大学で学ぶべきことは、すぐに役に立つ技術だけではないはずだ。むしろ、すぐには役に立たないように見える学問こそ、物事を深く考える力を育ててくれる。{哲学|てつがく}や歴史を学んだ経験が、何年も後になって、仕事上の難しい判断を支えてくれることもある。\n　もちろん、学生が将来に不安を持つのは当然であり、その不安に大学がこたえようとするのは悪いことではない。問題は、{就職|しゅうしょく}に直接つながるかどうかだけで授業の価値が判断されてしまうことだ。そうなれば、学生は目の前の結果ばかりを求め、時間をかけて考えるという、大学ならではの経験を失ってしまうだろう。\n　社会に出れば、正解のない問題に向き合う場面がいくらでもある。そのときに必要なのは、マニュアルどおりの答えではなく、自分の頭で考え抜く力である。大学には、その力を育てる場であり続けてほしい。","questions":[{"q":"キャリア教育について、本文ではどのように述べられているか。","options":["大学の授業としては必要がない。","学生にも受験生にも評判がいい。","面接の練習より講演のほうが役に立つ。","どの大学でも同じ内容が教えられている。"],"explain":"Students praise it (好評) and universities that focus on it are popular with applicants. The writer does not say it is unnecessary.","answer":1},{"q":"筆者によると、すぐには役に立たないように見える学問にはどんな良さがあるか。","options":["{就職活動|しゅうしょくかつどう}で{企業|きぎょう}から高く評価される。","{哲学|てつがく}や歴史の専門家になることができる。","仕事のマニュアルを早く覚えられるようになる。","物事を深く考える力が身につく。"],"explain":"Such studies 'nurture the ability to think deeply about things'.","answer":3},{"q":"筆者が最も言いたいことは何か。","options":["大学は、キャリア教育の授業をやめるべきだ。","学生は、将来に不安を持たないようにするべきだ。","大学は、自分の頭で考え抜く力を育てる場であるべきだ。","大学は、{就職|しゅうしょく}に役立つ授業をもっと増やすべきだ。"],"explain":"The conclusion: universities should remain places that develop the power to think things through oneself.","answer":2}]},{"text":"（２）\n　ある{中小企業|ちゅうしょうきぎょう}が、{社員同士|しゃいんどうし}で{感謝|かんしゃ}の気持ちを伝え合う「サンクスカード」という仕組みを取り入れた。{同僚|どうりょう}に助けてもらったときなどに、短いメッセージをカードに書いて渡すというものだ。導入した当初は、「わざわざ書くのは面倒だ」「形だけになるのではないか」という声も少なくなかったという。\n　ところが、半年ほどたつと、職場の{雰囲気|ふんいき}が目に見えて変わってきた。部署を越えて話をする機会が増え、困っている人がいると{誰|だれ}かがすぐに手を貸すようになったのだ。担当者によれば、特に効果が大きかったのは、普段あまり目立たない仕事をしている社員たちだった。データの入力や備品の管理など、できて当たり前と思われがちな仕事に対して{感謝|かんしゃ}の言葉が届くようになり、[[「自分の仕事が{誰|だれ}かの役に立っていると初めて実感できた」]]と話す人もいたそうだ。\n　人は、給料や評価のためだけに働いているわけではない。自分の存在が認められていると感じられるかどうかが、働く意欲を大きく左右する。とはいえ、カードを配ればそれで済むというものでもない。大切なのは、{日頃|ひごろ}から互いの仕事に関心を持ち、それを言葉にする習慣を、職場全体で育てていくことだろう。","questions":[{"q":"サンクスカードを導入した当初、社員の中にはどう感じていた人がいたか。","options":["部署を越えて話せるようになるので、うれしい。","手間がかかるうえ、意味のないものになるかもしれない。","カードをたくさんもらえば、給料が上がるだろう。","目立たない仕事をしている人だけがもらえるのは不公平だ。"],"explain":"At first some said writing cards was a bother (面倒) and might become a mere formality (形だけ).","answer":1},{"q":"[[「自分の仕事が{誰|だれ}かの役に立っていると初めて実感できた」]]とあるが、なぜそう感じたのか。","options":["当たり前だと思われていた仕事に、{感謝|かんしゃ}の言葉をもらったから","データ入力の仕事から、別の仕事に移ったから","上司から高く評価されて、給料が上がったから","困っている{同僚|どうりょう}を、自分から手伝うようになったから"],"explain":"Thanks started reaching people whose jobs were taken for granted (できて当たり前と思われがちな仕事).","answer":0},{"q":"筆者の考えに合うのはどれか。","options":["カードを配りさえすれば、職場の{雰囲気|ふんいき}は必ずよくなる。","働く意欲を高めるには、給料を上げるのが一番だ。","互いの仕事に関心を持ち、{感謝|かんしゃ}を言葉にする習慣が大切だ。","目立たない仕事は、できるだけ減らしていくべきだ。"],"explain":"The last sentence: what matters is a workplace-wide habit of noticing each other's work and putting thanks into words; cards alone are not enough.","answer":2}]},{"text":"（３）\n　中学校の部活動を、学校から地域のスポーツクラブや文化団体に任せていく動きが、各地で始まっている。背景にあるのは、教員の長時間労働の問題だ。部活動の指導のために、平日の放課後だけでなく土日も出勤する教員は珍しくない。授業の準備に十分な時間をかけられないという声も多く、教員を目指す若者が減っている一因とも言われている。\n　地域に任せることで、教員の負担が減るだけでなく、生徒にとってもよい点がある。専門的な知識を持つ指導者から教えてもらえるうえ、学校の{枠|わく}を越えて、さまざまな年齢の人と交流することができるからだ。\n　一方で、課題も少なくない。まず、指導者を十分に確保できる地域ばかりではない。特に人口の少ない地域では、引き受けてくれる人や団体がそもそも見つからないことがある。また、これまで無料だった活動に会費がかかるようになれば、家庭の経済的な事情によって、参加できる生徒とできない生徒が出てくるおそれもある。\n　部活動は多くの子供たちにとって、勉強以外で自分の居場所を見つけられる大切な場であった。制度を変えるにあたっては、どこに住んでいても、どんな家庭の子供でも、活動を続けられる仕組みを作ることが何より求められる。","questions":[{"q":"部活動を地域に任せる動きが始まった背景として、本文で{挙|あ}げられているのはどれか。","options":["部活動に参加する生徒が減ったこと","地域のスポーツクラブが増えたこと","{保護者|ほごしゃ}が専門的な指導を求めたこと","教員の働く時間が長すぎること"],"explain":"背景にあるのは、教員の長時間労働の問題だ.","answer":3},{"q":"本文によると、部活動を地域に任せることの課題はどれか。","options":["生徒が、ほかの年齢の人と交流できなくなること","費用がかかるために、参加できない生徒が出るかもしれないこと","教員が授業の準備をする時間が減ること","生徒が専門的な指導を受けられなくなること"],"explain":"If fees are charged, some students may be unable to take part for financial reasons. The other options are benefits or reversed.","answer":1},{"q":"筆者の考えに合うのはどれか。","options":["住んでいる地域や家庭の事情に関係なく、活動を続けられる仕組みが必要だ。","部活動は、これまでどおり学校の教員が指導するべきだ。","人口の少ない地域では、部活動をやめるべきだ。","部活動の会費は、すべて国が払うべきだ。"],"explain":"The final sentence asks for a system that lets any child, wherever they live and whatever their family situation, continue.","answer":0}]}]},{"sec":"dokkai","no":12,"type":"compare","instr":"次のAとBの文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"A\n　最近、社員の副業を認める{企業|きぎょう}が増えている。会社の外で働くことで、社員は本業では得られない知識や人とのつながりを得ることができる。それを本業に生かせば、会社にとっても{利益|りえき}になるはずだ。また、一つの会社に頼らずに収入を得る道を持っておくことは、変化の{激|はげ}しい時代を生きる個人にとって大きな安心になる。もちろん、働きすぎて体を{壊|こわ}しては意味がないので、労働時間の管理は必要だ。しかし、それを理由に副業を一律に禁止するのは、社員の可能性を狭めることになるのではないか。\n\nB\n　副業を認めることには、確かに利点もあるだろう。しかし、私は{慎重|しんちょう}に考えるべきだと思う。最も心配なのは、社員の健康である。本業の後や休日に別の仕事をすれば、休む時間はどうしても減る。疲れがたまれば、本業での事故やミスにもつながりかねない。さらに、会社の情報が外に{漏|も}れる危険もある。副業を認めるなら、まず会社が社員の働く時間をきちんと{把握|はあく}できる仕組みを作り、どのような仕事なら認めるのか、はっきりとしたルールを決めておくべきだ。","questions":[{"q":"AとBのどちらの文章でも触れられている点は何か。","options":["副業によって会社の情報が外に{漏|も}れる危険があること","副業で得た人とのつながりを本業に生かせること","副業によって働きすぎ、健康を損なうおそれがあること","副業を持つと個人の収入が安定すること"],"explain":"A: 働きすぎて体を壊しては意味がない; B: health is the biggest worry. Information leaks appear only in B; connections and income only in A.","answer":2},{"q":"副業について、AとBはどのように考えているか。","options":["Aは労働時間を管理せずに認めるべきだと考え、Bは全面的に禁止するべきだと考えている。","Aは一律に禁止するべきではないと考え、Bは条件を整えたうえで認めるべきだと考えている。","AもBも、副業は社員の可能性を広げるので、すぐに認めるべきだと考えている。","AもBも、副業は会社の{利益|りえき}にならないので、認めるべきではないと考えている。"],"explain":"A opposes a blanket ban; B would allow side jobs once time management and clear rules are in place — not a total ban.","answer":1}]}]},{"sec":"dokkai","no":13,"type":"opinion","instr":"次の文章を読んで、後の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"　子供のころ、私はテストで間違えることがとても怖かった。赤いペンで大きく×をつけられた答案用紙は、自分がだめな人間だという{証明|しょうめい}のように思えたからだ。間違えないためには、分からない問題には手を出さないのが一番安全だった。今{振|ふ}り返ると、私は学ぶことよりも、失敗しないことを目的にしていたのだと思う。\n　社会に出てからも、その傾向はなかなか変わらなかった。会議で意見を求められても、的外れなことを言って笑われるくらいなら{黙|だま}っていたほうがいいと考えていた。新しい仕事を任されそうになると、何かと理由をつけて断った。そうしているうちに、同期の中で私だけが取り残されていることに気づいた。彼らは失敗しなかったのではない。何度も失敗し、そのたびに周りに助けられながら、少しずつできることを増やしていたのだ。\n　考えてみれば、失敗とは、自分がまだ知らないことや、できないことを教えてくれる{貴重|きちょう}な情報である。どこで間違えたのかが分かれば、次に何をすればいいのかも見えてくる。逆に、失敗を{避|さ}け続けている人には、その情報が手に入らない。{挑戦|ちょうせん}しない人は、失敗しない代わりに、成長の手がかりも得られないのである。\n　ただし、これを個人の心がけだけの問題にするのは公平ではない。失敗した人を{厳|きび}しく責め、二度と{挑戦|ちょうせん}できないような{雰囲気|ふんいき}がある職場や学校では、{誰|だれ}もが{慎重|しんちょう}になるのは当然だ。「失敗を恐れるな」と言うのは簡単だが、言う側には、失敗しても{大丈夫|だいじょうぶ}だと思える環境を整える責任がある。たとえば、結果だけでなく{挑戦|ちょうせん}したこと自体を評価する、失敗の原因を個人の能力ではなく仕組みの問題として話し合う、といった工夫は、どの{組織|そしき}でもすぐに始められるはずだ。\n　最近、私は部下が失敗の報告に来たとき、まず「話してくれてありがとう」と言うようにしている。{叱|しか}られると思って身構えていた部下の表情が、ふっと{緩|ゆる}むのが分かる。失敗を{隠|かく}さずに話せる関係があってこそ、{組織|そしき}は同じ失敗を{繰|く}り返さずにすむ。子供のころの私に必要だったのも、×の数ではなく、間違えた理由を一緒に考えてくれる大人だったのかもしれない。","questions":[{"q":"筆者は、子供のころの自分をどのように{振|ふ}り返っているか。","options":["テストの点数がいつも悪く、勉強が{嫌|きら}いだった。","分からない問題があると、すぐ先生に質問していた。","間違えた理由を、大人と一緒によく考えていた。","学ぶことよりも、間違えないことを大切にしていた。"],"explain":"学ぶことよりも、失敗しないことを目的にしていた. The last option is what he says he lacked.","answer":3},{"q":"筆者によると、失敗を{避|さ}け続けるとどうなるか。","options":["成長するための手がかりが得られない。","周りの人から信頼されるようになる。","同期よりも早く仕事ができるようになる。","新しい仕事を任される機会が増える。"],"explain":"挑戦しない人は、失敗しない代わりに、成長の手がかりも得られない.","answer":0},{"q":"この文章で筆者が最も言いたいことは何か。","options":["失敗を恐れるかどうかは、個人の性格で決まるものだ。","失敗を恐れずに{挑戦|ちょうせん}できるよう、周りが環境を整えることが大切だ。","失敗した人は{厳|きび}しく{叱|しか}り、同じ失敗をさせないようにするべきだ。","{組織|そしき}では、{挑戦|ちょうせん}したことよりも結果を評価するべきだ。"],"explain":"The writer says it's unfair to make it only an individual issue; those who say 'don't fear failure' must create an environment where failing is safe.","answer":1}]}]},{"sec":"dokkai","no":14,"type":"info","instr":"次は、みどり市の講座の案内である。下の問いに対する答えとして最もよいものを、１・２・３・４から一つ選びなさい。","passages":[{"text":"みどり市　社会人のためのスキルアップ講座　受講生募集\n\nみどり市では、市内に住んでいる方、または市内に通勤している方を対象に、仕事に役立つ講座を開講します。\n\n【講座{一覧|いちらん}】\n講座｜内容｜日時｜回数｜受講料｜定員\nＡ｜ビジネス文書の書き方｜毎週火曜 19:00〜20:30｜全4回｜3,000円｜20名\nＢ｜はじめての表計算ソフト｜毎週土曜 10:00〜12:00｜全6回｜5,000円｜15名\nＣ｜プレゼンテーション入門｜毎週木曜 19:00〜21:00｜全4回｜4,000円｜20名\nＤ｜外国人のお客様への接客英語｜毎週日曜 14:00〜16:00｜全5回｜4,000円｜25名\n\n※講座Ｂは、ノートパソコンをお持ちの方のみ受講できます（各自持参）。\n※講座Ｃ・Ｄは、市内の{企業|きぎょう}にお勤めの方は受講料が半額になります。申し込みの際に{在職証明書|ざいしょくしょうめいしょ}を{提出|ていしゅつ}してください。\n\n【申し込み方法】\n・市のホームページの申し込みフォーム、または市民センターの窓口でお申し込みください。\n・申し込み期間：5月1日〜5月15日\n・定員を超えた場合は{抽選|ちゅうせん}となります。結果は5月22日までにメールでお知らせします。\n・受講料は、初回の講座の日に会場でお支払いください。\n\n【問い合わせ】みどり市市民センター　{学習支援課|がくしゅうしえんか}","questions":[{"q":"ワンさんは、みどり市に住んでいて、市外の会社で働いている。平日は毎日夜9時まで会社にいる。ノートパソコンは持っていない。ワンさんが受講できる講座はどれか。","options":["Ａのみ","Ｂのみ","Ｄのみ","ＢとＤ"],"explain":"Weekday evening courses (A, C) are impossible; B (Saturday) requires bringing a laptop. Only D (Sunday) remains. He lives in the city, so he is eligible.","answer":2},{"q":"市内の会社に勤めている田中さんは、講座Ｃを受講したいと考えている。田中さんがしなければならないことはどれか。","options":["5月15日までに申し込み、初回の講座の日に{在職証明書|ざいしょくしょうめいしょ}を出して4,000円を払う。","5月22日までに{在職証明書|ざいしょくしょうめいしょ}を出して申し込み、申し込みの際に2,000円を払う。","5月15日までに{在職証明書|ざいしょくしょうめいしょ}を出して申し込み、初回の講座の日に2,000円を払う。","5月15日までに申し込み、申し込みの際に4,000円を払う。"],"explain":"Working in the city halves C's fee to 2,000 yen; the employment certificate goes in with the application (by May 15); payment is at the first class.","answer":2}]}]}]},"l":{"mondai":[{"no":1,"type":"task","instr":"問題1では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。","items":[{"intro":"会社で女の人と男の人が話しています。男の人はこのあとまず何をしなければなりませんか。","question":"男の人はこのあとまず何をしなければなりませんか。","lines":[{"sp":"F","ja":"田中さん、明日のA社との打ち合わせの件なんだけど、資料はもうできてる？","en":"Tanaka, about tomorrow's meeting with Company A — are the materials ready?"},{"sp":"M","ja":"はい、さっき完成しました。これから二十部コピーしようと思ってたところです。","en":"Yes, I just finished them. I was about to make twenty copies."},{"sp":"F","ja":"あ、それがね、先方の参加者が増えて、会議室も大きいほうに変わったの。","en":"Oh, about that — more people are coming from their side, so the meeting room has changed to the bigger one."},{"sp":"M","ja":"そうなんですか。じゃあ、コピーは三十部にしますね。","en":"Really? Then I'll make thirty copies."},{"sp":"F","ja":"うん。でもその前に、資料の三ページ目の数字、先月のままになってない？ 昨日、経理から新しいのが来てたでしょう。","en":"OK. But before that, aren't the figures on page three still last month's? Accounting sent new ones yesterday."},{"sp":"M","ja":"あ、本当だ。すぐ直します。","en":"Oh, you're right. I'll fix them right away."},{"sp":"F","ja":"コピーはそのあとでいいから。会議室の予約の変更は私がやっておくね。","en":"The copies can wait until after that. I'll take care of changing the room booking."},{"sp":"M","ja":"ありがとうございます。あ、先方にお送りする案内のメールは…","en":"Thank you. Oh, and the information email to send them..."},{"sp":"F","ja":"それは直した資料ができてから、一緒に送ってくれればいいよ。","en":"Send that together with the corrected materials once they're done."}],"options":["資料の数字を直す","資料をコピーする","会議室の予約を変える","案内のメールを送る"],"explain":"He must first correct the figures on page 3; copying and the email come after, and the woman will change the room booking.","answer":0},{"intro":"大学の事務室で男の学生と職員が話しています。男の学生は、申込書のほかに何を準備しなければなりませんか。","question":"男の学生は、申込書のほかに何を準備しなければなりませんか。","lines":[{"sp":"M","ja":"すみません、{奨学金|しょうがくきん}の申し込みをしたいんですが。","en":"Excuse me, I'd like to apply for a scholarship."},{"sp":"F","ja":"はい。こちらの申込書と、{成績証明書|せいせきしょうめいしょ}、それから家族の収入がわかる書類が必要です。","en":"Sure. You need this application form, a transcript, and a document showing your family's income."},{"sp":"M","ja":"{成績証明書|せいせきしょうめいしょ}は、ここで出してもらえますか。","en":"Can I get the transcript issued here?"},{"sp":"F","ja":"{証明書|しょうめいしょ}の発行機で、{学生証|がくせいしょう}があればすぐ出せますよ。あ、でもあなた、一年生ですよね。","en":"The certificate machine can print it right away with your student ID. Oh, but you're a first-year, aren't you?"},{"sp":"M","ja":"はい。","en":"Yes."},{"sp":"F","ja":"一年生は大学での成績がまだないので、高校の{成績証明書|せいせきしょうめいしょ}になります。高校に頼んで送ってもらってください。","en":"First-years don't have university grades yet, so it has to be your high-school transcript. Please ask your high school to send it."},{"sp":"M","ja":"わかりました。収入の書類は…","en":"I see. And the income document..."},{"sp":"F","ja":"それは、今日持ってきてくださったもので{大丈夫|だいじょうぶ}です。申込書は、{締|し}め切りの金曜までに出してくれればいいですよ。","en":"The one you brought today is fine. You can hand in the form any time before Friday's deadline."}],"options":["大学の{成績証明書|せいせきしょうめいしょ}","家族の収入がわかる書類","{学生証|がくせいしょう}のコピー","高校の{成績証明書|せいせきしょうめいしょ}"],"explain":"As a first-year he needs his high-school transcript; the income document he already brought is acceptable.","answer":3},{"intro":"会社で男の人と女の人が話しています。女の人はまず何をしますか。","question":"女の人はまず何をしますか。","lines":[{"sp":"M","ja":"{鈴木|すずき}さん、来週から入る新人の研修、担当してもらえるかな。","en":"Suzuki, could you be in charge of training the newcomers who start next week?"},{"sp":"F","ja":"はい。何から準備すればいいでしょうか。","en":"Sure. What should I prepare first?"},{"sp":"M","ja":"去年の研修のスケジュールがあるから、それをもとに作ってくれればいいよ。ただ、今年は営業部に行く人が多いから、営業の内容を少し増やしたいんだ。","en":"There's last year's schedule, so you can base it on that. But this year many of them are going to Sales, so I'd like a bit more sales content."},{"sp":"F","ja":"わかりました。じゃあ、まず営業部の山本さんに、どんな内容がいいか聞いてみます。","en":"Understood. Then I'll first ask Yamamoto in Sales what content would be good."},{"sp":"M","ja":"あ、山本さんは今週出張でいないんだよ。でも、去年のアンケートに営業部からの要望が書いてあったはずだから、まずそれを見てみて。","en":"Ah, Yamamoto is away on business this week. But last year's questionnaire should include requests from Sales, so look at that first."},{"sp":"F","ja":"はい。アンケートは共有フォルダにありますか。","en":"OK. Is the questionnaire in the shared folder?"},{"sp":"M","ja":"うん。それを読んでから、スケジュールの案を作ってくれる？","en":"Yes. After reading it, could you draft the schedule?"}],"options":["去年のスケジュールを見る","去年のアンケートを読む","山本さんに話を聞く","スケジュールの案を作る"],"explain":"Yamamoto is away, so she should read last year's questionnaire first, then draft the schedule.","answer":1},{"intro":"市役所で男の人と係の人が話しています。男の人はこのあとまず何をしますか。","question":"男の人はこのあとまず何をしますか。","lines":[{"sp":"M","ja":"すみません、先週こちらに引っ越してきたんですが、住所の変更はこちらでいいですか。","en":"Excuse me, I moved here last week. Is this the place for a change of address?"},{"sp":"F","ja":"はい、こちらの窓口です。この用紙に書いて、本人確認ができるものと一緒に出してください。","en":"Yes, this counter. Fill in this form and hand it in with some ID."},{"sp":"M","ja":"はい。あと、子どもの小学校の転校の手続きもしたいんですが。","en":"OK. I'd also like to do the procedure for my child's transfer to a new elementary school."},{"sp":"F","ja":"それは二階の教育委員会の窓口になります。ただ、住所の変更が終わってからでないと手続きできませんので、先にこちらを済ませてください。","en":"That's the Board of Education counter on the second floor. But you can't do it until the address change is finished, so please complete this first."},{"sp":"M","ja":"わかりました。","en":"I see."},{"sp":"F","ja":"では、用紙をお書きになったら、番号札を取ってお待ちください。","en":"Then, once you've filled in the form, take a number ticket and wait."},{"sp":"M","ja":"あ、すみません、本人確認の…{運転免許証|うんてんめんきょしょう}、車に置いてきちゃった。ちょっと取ってきます。","en":"Oh, sorry, my ID... I left my driver's licence in the car. I'll just go and get it."},{"sp":"F","ja":"はい、どうぞ。","en":"Sure, go ahead."}],"options":["用紙を書いて窓口に出す","二階の窓口へ行く","番号札を取って待つ","{運転免許証|うんてんめんきょしょう}を取りに行く"],"explain":"He left his ID in the car and goes to get it first; the school transfer must wait until the address change is done.","answer":3},{"intro":"会社で女の人と部長が話しています。女の人はこのあと何をしますか。","question":"女の人はこのあと何をしますか。","lines":[{"sp":"F","ja":"部長、来月の{創立記念|そうりつきねん}パーティーの会場なんですが、候補のホテルが二つありまして。","en":"Sir, about the venue for next month's founding anniversary party — there are two candidate hotels."},{"sp":"M","ja":"うん。","en":"Uh-huh."},{"sp":"F","ja":"駅前のホテルは料金が少し高いんですが、二百人入れます。もう一つは安いんですが、百五十人までで…","en":"The hotel by the station is a bit expensive but holds 200 people. The other is cheaper but only holds up to 150..."},{"sp":"M","ja":"参加者は何人ぐらいになりそう？","en":"How many participants are we expecting?"},{"sp":"F","ja":"今のところ百六十人ぐらいの予定です。","en":"About 160 at the moment."},{"sp":"M","ja":"じゃあ、駅前しかないね。予約はもう取れる？","en":"Then it has to be the one by the station. Can we book it now?"},{"sp":"F","ja":"仮予約はしてあるので、正式に申し込めばいいだけです。ただ、料金が予算を少し超えてしまうので…","en":"I've made a provisional booking, so I'd only need to apply formally. But the cost goes slightly over budget..."},{"sp":"M","ja":"そうか。それなら、先に経理に予算を増やせるか確認してくれる？ 返事を聞いてから申し込もう。","en":"I see. In that case, could you first check with Accounting whether the budget can be increased? We'll apply after we hear back."},{"sp":"F","ja":"わかりました。","en":"Certainly."}],"options":["経理に予算について聞く","ホテルに正式に申し込む","参加者の人数を確認する","もう一つのホテルを予約する"],"explain":"The manager tells her to check with Accounting about the budget first; the formal booking comes after their reply.","answer":0}]},{"no":2,"type":"point","instr":"問題2では、まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。読む時間があります。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。","items":[{"intro":"会社で男の人と女の人が話しています。女の人はどうして会社を辞めることにしましたか。","question":"女の人はどうして会社を辞めることにしましたか。","lines":[{"sp":"M","ja":"{佐藤|さとう}さん、来月で辞めるって本当？","en":"Sato, is it true you're leaving next month?"},{"sp":"F","ja":"うん。実は前から考えてたんだ。","en":"Yes. Actually I'd been thinking about it for a while."},{"sp":"M","ja":"給料が不満だったとか？","en":"Were you unhappy with the pay?"},{"sp":"F","ja":"ううん、給料は悪くなかったよ。人間関係もよかったし。","en":"No, the pay wasn't bad. And I got on well with everyone."},{"sp":"M","ja":"じゃあ、通勤？ 片道一時間半だったよね。","en":"Then the commute? It was an hour and a half each way, right?"},{"sp":"F","ja":"それも大変だったけど、もう慣れたから。実はね、大学で勉強した環境の分野の仕事がずっとしたくて。今度の会社では、まさにその仕事ができるの。","en":"That was tough too, but I got used to it. The truth is, I've always wanted to work in the environmental field I studied at university, and at the new company I can do exactly that."},{"sp":"M","ja":"そうなんだ。通勤は楽になるの？","en":"I see. Will the commute be easier?"},{"sp":"F","ja":"それが、今より遠くなっちゃうんだけどね。","en":"Actually, it'll be even further than now."}],"options":["給料が安いから","通勤に時間がかかるから","やりたかった仕事ができるから","職場の人間関係がよくないから"],"explain":"Pay and relationships were fine, and the new commute is even longer; she is leaving to work in the environmental field.","answer":2},{"intro":"大学で先生と男の学生が話しています。先生は、学生のレポートの何が一番の問題だと言っていますか。","question":"先生は、学生のレポートの何が一番の問題だと言っていますか。","lines":[{"sp":"F","ja":"山田さん、この前のレポート、読みましたよ。","en":"Yamada, I read your recent report."},{"sp":"M","ja":"ありがとうございます。どうでしたか。","en":"Thank you. How was it?"},{"sp":"F","ja":"テーマはおもしろいし、資料もよく集めてありましたね。","en":"The theme is interesting, and you gathered plenty of material."},{"sp":"M","ja":"はい、図書館で一週間かけて調べました。","en":"Yes, I spent a week researching at the library."},{"sp":"F","ja":"それはよくわかります。ただ、集めた資料を紹介しているだけで、山田さん自身がどう考えるのかが、ほとんど書かれていないんです。","en":"That's clear. But you only introduce the material you collected; there's almost nothing about what you yourself think."},{"sp":"M","ja":"ああ…。","en":"Ah..."},{"sp":"F","ja":"長さも十分だし、誤字も少ない。でも、レポートは自分の意見を、{根拠|こんきょ}を示して述べるものですからね。次はそこを意識してください。","en":"The length is sufficient and there are few typos. But a report is where you state your own opinion with evidence. Keep that in mind next time."}],"options":["自分の考えが書かれていないこと","テーマがおもしろくないこと","資料が足りないこと","誤字が多いこと"],"explain":"Theme, materials, length and typos are all fine; the problem is that his own view is missing.","answer":0},{"intro":"ラジオで、アナウンサーが会社の社長にインタビューしています。社長は、会社が{成功|せいこう}した一番の理由は何だと言っていますか。","question":"社長は、会社が{成功|せいこう}した一番の理由は何だと言っていますか。","lines":[{"sp":"F","ja":"御社の商品は若い世代にも人気ですが、{成功|せいこう}の理由は何だとお考えですか。","en":"Your products are popular with young people too. What do you think is the reason for your success?"},{"sp":"M","ja":"よく、デザインがいいからだと言っていただくんですが、それより大きいのは、お客様の声を聞く仕組みだと思っています。","en":"People often kindly say it's the design, but I think what matters more is our system for listening to customers."},{"sp":"F","ja":"と言いますと？","en":"Meaning?"},{"sp":"M","ja":"毎月、実際に商品を使っている方に集まっていただいて、直接ご意見を伺うんです。不満な点を聞いて、すぐに改良する。それを十年続けてきました。","en":"Every month we gather people who actually use our products and hear their opinions directly. We listen to complaints and improve things immediately. We've kept that up for ten years."},{"sp":"F","ja":"価格も手ごろですよね。","en":"Your prices are reasonable too."},{"sp":"M","ja":"ええ。ただ、価格だけで選ばれる商品は、もっと安いものが出ればすぐに負けてしまいますから。","en":"Yes. But products chosen only for price lose as soon as something cheaper appears."}],"options":["商品のデザインがいいこと","商品の値段が安いこと","客の意見をもとに商品を改良してきたこと","若い世代の社員が多いこと"],"explain":"He says more important than design is listening to customers monthly and improving products; price alone is not a lasting reason.","answer":2},{"intro":"男の人と女の人が話しています。男の人はどうして日曜日のボランティアに参加できませんか。","question":"男の人はどうして日曜日のボランティアに参加できませんか。","lines":[{"sp":"F","ja":"田中さん、日曜日の公園の清掃ボランティア、今回も来られる？","en":"Tanaka, can you come to the park clean-up volunteering on Sunday again this time?"},{"sp":"M","ja":"それが、行きたいんだけど、だめなんだ。","en":"Well, I'd like to, but I can't."},{"sp":"F","ja":"あ、お子さんの運動会？ 先月そう言ってたよね。","en":"Oh, your child's sports day? You mentioned it last month."},{"sp":"M","ja":"いや、運動会は雨で来月に延びたんだ。","en":"No, sports day was postponed to next month because of rain."},{"sp":"F","ja":"じゃあ、お仕事？","en":"Work, then?"},{"sp":"M","ja":"仕事は休みなんだけど、実は母が入院してて、日曜は病院に行くことになってるんだ。","en":"I'm off work, but actually my mother's in hospital, and I'm going to visit her on Sunday."},{"sp":"F","ja":"そうだったの。お大事にね。","en":"Oh, I didn't know. I hope she gets well soon."}],"options":["子どもの運動会があるから","母親のいる病院に行くから","仕事があるから","雨が降りそうだから"],"explain":"Sports day was postponed and he's off work; he is visiting his mother in hospital.","answer":1},{"intro":"会社で男の人と女の人が新しいシステムについて話しています。女の人は、何が一番困ると言っていますか。","question":"女の人は、新しいシステムの何が一番困ると言っていますか。","lines":[{"sp":"M","ja":"新しい{勤怠管理|きんたいかんり}システム、どう？ 使いにくいって言う人もいるけど。","en":"How do you find the new attendance system? Some people say it's hard to use."},{"sp":"F","ja":"画面は見やすくなったと思う。操作も慣れれば簡単だし。","en":"I think the screens are easier to read. And it's simple once you get used to it."},{"sp":"M","ja":"スマホからも出勤の記録ができるようになったしね。","en":"And now you can clock in from your phone too."},{"sp":"F","ja":"うん、それは便利。ただ、{休暇|きゅうか}の{申請|しんせい}がね。前は紙で出せば、その日のうちに課長がはんこを押してくれたのに、今は部長まで承認が回るから、決まるまで三日もかかるの。急に休みが必要なとき、本当に困るんだよね。","en":"Yes, that's handy. The problem is leave requests. Before, the section chief stamped the paper form the same day, but now approval goes up to the department head, so it takes three days. That's a real problem when you suddenly need a day off."}],"options":["画面が見にくいこと","操作が難しいこと","スマホから使えないこと","休みの{申請|しんせい}が認められるまで時間がかかること"],"explain":"She praises screen, operation and phone access; the problem is that leave approval now takes three days.","answer":3},{"intro":"大学の説明会で、先生が話しています。先生は、この学部の一番の{特徴|とくちょう}は何だと言っていますか。","question":"先生は、この学部の一番の{特徴|とくちょう}は何だと言っていますか。","lines":[{"sp":"M","ja":"本学部の{特徴|とくちょう}についてお話しします。よく「留学制度が{充実|じゅうじつ}している」と言われますし、実際に半数以上の学生が在学中に留学しますが、それはほかの大学にもある制度です。私たちが最も力を入れているのは、一年生から始まる、地域の{企業|きぎょう}との共同プロジェクトです。学生がチームを作り、実際の{企業|きぎょう}の課題に取り組みます。教室で学んだ理論を現場で試し、失敗し、また教室に戻って考える。この{繰|く}り返しこそが、本学部ならではの学びです。もちろん、少人数のゼミも{魅力|みりょく}の一つですが…。","en":"Let me talk about this faculty's features. People often say our study-abroad system is excellent, and indeed over half our students study abroad, but other universities have that too. What we put most effort into is joint projects with local companies starting in the first year. Students form teams and tackle real corporate problems. They test theory from class in the field, fail, and come back to the classroom to think again. This cycle is the learning unique to our faculty. Of course, our small seminars are another attraction..."}],"options":["留学する学生が多いこと","少人数のゼミがあること","理論を学ぶ授業が多いこと","一年生から{企業|きぎょう}と一緒に課題に取り組むこと"],"explain":"Study abroad exists elsewhere too; what they emphasise most is first-year joint projects with local companies.","answer":3}]},{"no":3,"type":"gist","instr":"問題3では、問題用紙に何も印刷されていません。この問題は、全体としてどんな内容かを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。","items":[{"intro":"ラジオで、専門家が話しています。","question":"専門家は何について話していますか。","lines":[{"sp":"M","ja":"会議が長くて仕事が進まない、という悩みをよく聞きます。会議を短くするには、まず目的をはっきりさせることです。情報を伝えるだけなら、メールで十分な場合も多いんです。次に、参加者を必要な人だけに{絞|しぼ}ること。人数が多いほど、発言しない人が増え、時間ばかりかかります。そして、終わりの時間を最初に決めておく。この三つを守るだけで、会議の時間は半分ほどになると言われています。","en":"I often hear complaints that long meetings stop work getting done. To shorten meetings, first make the purpose clear. If it's just sharing information, email is often enough. Next, limit attendees to those who are needed. The more people, the more who don't speak, and the longer it takes. And decide the end time at the start. It's said that following these three alone roughly halves meeting time."}],"options":["会議の時間を短くする方法","メールの上手な書き方","会議で発言するときの注意","会議の参加者を増やす理由"],"explain":"He gives three tips for shortening meetings; email and speaking up are only details.","answer":0},{"intro":"大学の授業で、先生が話しています。","question":"先生は何について話していますか。","lines":[{"sp":"F","ja":"かつて日本の{企業|きぎょう}では、一度{就職|しゅうしょく}すれば定年まで同じ会社で働くのが一般的でした。会社は社員を長い時間をかけて育て、社員は会社のために{尽|つ}くす、という関係があったわけです。しかし、経済の成長が止まり、会社が社員の一生を{保証|ほしょう}することは難しくなりました。今では転職は珍しいことではありませんし、会社の側も、必要な能力を持つ人を途中から採用するようになっています。こうした変化によって、働く人は、会社に頼るのではなく、自分で能力を高め続けることが求められるようになったのです。","en":"In the past, at Japanese companies it was normal, once hired, to work for the same company until retirement. Companies trained employees over a long time, and employees devoted themselves to the company. But economic growth stopped, and it became hard for companies to guarantee employees' whole careers. Now changing jobs isn't unusual, and companies hire people with the skills they need mid-career. Because of these changes, workers are now expected to keep improving their own abilities rather than rely on their company."}],"options":["日本の会社の社員教育の方法","転職を{成功|せいこう}させるための方法","日本の雇用のあり方の変化","経済の成長が止まった理由"],"explain":"The lecture traces how lifetime employment gave way to job changes and mid-career hiring — a change in employment practices.","answer":2},{"intro":"テレビで、レポーターが話しています。","question":"レポーターは主に何について伝えていますか。","lines":[{"sp":"F","ja":"こちらは、今年リニューアルしたみなみ市立図書館です。ご{覧|らん}ください、館内で話をしている人がたくさんいますね。この図書館では、静かに本を読むエリアとは別に、会話をしてもいい広いスペースを作りました。学生がグループで勉強したり、地域の人が集まって勉強会を開いたりしています。また、仕事を探している人のための相談会や、起業についてのセミナーも毎月開かれています。本を借りる場所から、人が集まり学び合う場所へ。図書館の役割が変わりつつあるようです。","en":"This is Minami City Library, renovated this year. Look — lots of people are talking inside. Apart from the quiet reading area, this library has created a large space where conversation is allowed. Students study in groups, and local people gather to hold study sessions. There are also monthly consultations for job seekers and seminars on starting a business. From a place to borrow books to a place where people gather and learn from each other — the library's role seems to be changing."}],"options":["図書館で静かに本を読む人が減ったこと","図書館が人の集まる学びの場に変わってきたこと","図書館で仕事を探す人が増えたこと","図書館の本の数が増えたこと"],"explain":"The report's point is the changing role of the library: from lending books to a place where people gather and learn.","answer":1},{"intro":"会社で、男の人と女の人が新商品について話しています。","question":"女の人は新商品についてどう思っていますか。","lines":[{"sp":"M","ja":"来月発売のお{弁当|べんとう}の新商品、試食してみた？ 野菜を多く使って健康的にしたんだけど。","en":"Did you try the new boxed lunch launching next month? We made it healthy with lots of vegetables."},{"sp":"F","ja":"うん。味はすごくいいと思う。野菜もたっぷりで、ヘルシーなのもいいよね。","en":"Yes. I think it tastes great. Plenty of vegetables, and being healthy is a plus."},{"sp":"M","ja":"よかった。","en":"Good."},{"sp":"F","ja":"ただ、この値段だと、毎日お昼に買う会社員には、ちょっと手が出にくいんじゃないかな。量のわりに高く感じるかも。健康のためなら高くても買う、っていう人ばかりじゃないし。","en":"But at this price, it might be hard for office workers who buy lunch every day. It may feel expensive for the amount. Not everyone will pay more for health."},{"sp":"M","ja":"そうか…。","en":"I see..."},{"sp":"F","ja":"味がいいだけに、もったいないと思う。","en":"Precisely because it tastes so good, it seems a waste."}],"options":["味も値段もちょうどいい。","味はいいが、値段が高すぎる。","値段は安いが、味がよくない。","野菜が少なくて、健康的ではない。"],"explain":"She praises the taste and vegetables but thinks the price is too high for daily office lunches.","answer":1},{"intro":"講演会で、町の職員が話しています。","question":"男の人が一番言いたいことは何ですか。","lines":[{"sp":"M","ja":"この町では、ここ十年で、外国から来て働く人が三倍に増えました。工場や農業の現場では、もう欠かせない存在です。ところが、言葉の壁のために、ごみの出し方が分からない、病院でうまく{症状|しょうじょう}を伝えられないといった問題も起きています。町では三年前から、地域のボランティアによる日本語教室を開いていますが、教室は日本語を教えるだけの場所ではありません。{住民同士|じゅうみんどうし}が知り合い、困ったときに助け合える関係を作る場所にもなっているんです。外国人住民を「お客さん」ではなく、同じ町に暮らす仲間として迎える。それが、これからの町づくりに必要なことだと思います。","en":"In this town, the number of people who came from abroad to work has tripled in the last ten years. They are now indispensable in factories and on farms. But because of the language barrier, problems arise — not knowing how to put out rubbish, being unable to explain symptoms at hospital. For three years the town has run Japanese classes with local volunteers, but the classes aren't just for teaching Japanese. They are also places where residents get to know each other and build relationships to help one another. Welcoming foreign residents not as 'guests' but as fellow members of the same town — I believe that's what future town-building needs."}],"options":["外国人住民は、まずごみの出し方を学ぶべきだ。","日本語教室のボランティアが足りなくて困っている。","外国人住民を同じ町の仲間として迎えることが大切だ。","工場で働く外国人をもっと増やすべきだ。"],"explain":"His conclusion: welcome foreign residents as fellow townspeople, not guests.","answer":2}]},{"no":4,"type":"response","instr":"問題4では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。","items":[{"intro":"","question":"","lines":[{"sp":"F","ja":"部長、例の件でしたら、先方にはもうお伝えしてあります。","en":"Sir, regarding that matter, I've already informed the other party."}],"options":["そうか、手間が省けて助かるよ。","じゃあ、早く伝えておいてくれる？","え、まだ伝えてないの？"],"explain":"It's already done, so the manager thanks her. The other replies assume it hasn't been done.","answer":0},{"intro":"","question":"","lines":[{"sp":"M","ja":"山田さんの{企画|きかく}が会議で通るとは、思ってもみなかったよ。","en":"I never imagined Yamada's proposal would get through the meeting."}],"options":["じゃあ、会議に出してみたらどうですか。","本当ですね、私もびっくりしました。","え、通らなかったんですか。"],"explain":"〜とは思ってもみなかった = it passed, unexpectedly. Surprise is the natural reaction.","answer":1},{"intro":"","question":"","lines":[{"sp":"F","ja":"すみません、この書類、今日中にっていうわけにはいきませんか。","en":"Sorry, is there no way you could do these documents today?"}],"options":["ええ、今日はわけがありません。","じゃあ、今日中にはいかないでください。","申し{訳|わけ}ありません、どうしても明日になってしまいます。"],"explain":"She is asking if it can be finished today; the fitting reply apologises that it must be tomorrow.","answer":2},{"intro":"","question":"","lines":[{"sp":"M","ja":"今度の担当の人、仕事が早いのなんのって。","en":"The new person in charge — talk about working fast!"}],"options":["え、そんなに遅いんですか。","何が早いのか聞いてみましょうか。","へえ、そんなに早いんですか。"],"explain":"〜のなんのって emphasises an extreme degree: they are extremely fast.","answer":2},{"intro":"","question":"","lines":[{"sp":"F","ja":"会議の資料、人数分コピーしておいてもらえると助かるんだけど。","en":"It would help if you could copy the meeting materials for everyone."}],"options":["はい、おかげで助かりました。","わかりました、すぐやります。","コピーしておいてもらいました。"],"explain":"It's an indirect request; agreeing to do it is the natural reply.","answer":1},{"intro":"","question":"","lines":[{"sp":"M","ja":"この前の発表、{緊張|きんちょう}のあまり、何を話したか全然覚えてないんだ。","en":"At that presentation I was so nervous I don't remember what I said at all."}],"options":["でも、落ち着いているように見えたよ。","じゃあ、ちゃんと覚えておいてね。","{緊張|きんちょう}しなくてよかったね。"],"explain":"〜のあまり = so (nervous) that... Reassuring him that he looked calm fits.","answer":0},{"intro":"","question":"","lines":[{"sp":"F","ja":"田中君、来週の出張、行ってもらうことになるかもしれないから、そのつもりでいてね。","en":"Tanaka, you might end up going on next week's business trip, so be prepared for that."}],"options":["えっ、もう行ってきたんですか。","わかりました。予定を空けておきます。","じゃあ、行かなくてもいいんですね。"],"explain":"そのつもりでいて = be ready for it; he should keep his schedule free.","answer":1},{"intro":"","question":"","lines":[{"sp":"M","ja":"{締|し}め切りに間に合ったからいいようなものの、もう少し早く始めるべきだったね。","en":"It's a good thing you made the deadline, but you should have started a bit earlier."}],"options":["間に合わなくて、すみませんでした。","早く始めてよかったですね。","はい、次からは気をつけます。"],"explain":"〜からいいようなものの = it worked out, but it's a mild reprimand; promising to be careful fits.","answer":2},{"intro":"","question":"","lines":[{"sp":"F","ja":"新製品の売り上げ、予想を上回るどころか、半分にも届いていないんです。","en":"Sales of the new product — far from beating forecasts, they haven't even reached half."}],"options":["それは、何か{対策|たいさく}を考えないとね。","予想以上だなんて、すごいね。","半分も売れたなら、いいじゃない。"],"explain":"〜どころか = far from X; sales are bad, so countermeasures are needed.","answer":0},{"intro":"","question":"","lines":[{"sp":"M","ja":"先方からの返事、待っていても仕方ないし、こちらから電話してみたら？","en":"There's no point waiting for their reply — why not call them yourself?"}],"options":["はい、待っていてよかったです。","そうですね、そうします。","先方から電話してもらいました。"],"explain":"It's a suggestion to call; accepting it is the natural reply.","answer":1},{"intro":"","question":"","lines":[{"sp":"F","ja":"お忙しいところ、わざわざお越しいただいて{恐縮|きょうしゅく}です。","en":"I'm sorry to have you come all this way when you're so busy."}],"options":["いえいえ、近くまで来る用事がありましたので。","いえ、お越しにならなくても{大丈夫|だいじょうぶ}です。","はい、忙しくて大変でした。"],"explain":"A polite reply downplays the trouble. Using お越しになる about oneself is wrong, and agreeing it was a hassle is rude.","answer":0},{"intro":"","question":"","lines":[{"sp":"M","ja":"来年度の予算、もし{削|けず}られるとしたら、どこから{削|けず}る？","en":"If next year's budget gets cut, where would you cut first?"}],"options":["来年度は予算が増えたんだね。","{削|けず}られてよかったね。","やっぱり、広告費からかな。"],"explain":"It's a hypothetical question about what to cut; naming an item answers it.","answer":2}]},{"no":5,"type":"integrated","instr":"問題5では、長めの話を聞きます。この問題には練習はありません。メモをとってもかまいません。","items":[{"intro":"問題用紙に何も印刷されていません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。\n大学の{就職課|しゅうしょくか}で、職員と男の学生が話しています。","question":"男の学生はどのインターンシップに申し込みますか。","lines":[{"sp":"F","ja":"今募集しているインターンシップは四つあります。一つ目は食品メーカーで、期間は二週間。商品開発の会議にも参加できます。二つ目は旅行会社で、一週間。実際にお店でお客様の対応をします。三つ目はIT{企業|きぎょう}で、一か月。プログラミングの経験が必要です。四つ目は新聞社で、三日間ですが、記者と一緒に取材に行けます。","en":"There are four internships open now. The first is at a food manufacturer, for two weeks; you can join product-development meetings. The second is at a travel agency, for one week; you actually serve customers in a shop. The third is at an IT company, for a month; programming experience is required. The fourth is at a newspaper, only three days, but you can go out reporting with a journalist."},{"sp":"M","ja":"{僕|ぼく}、将来はマーケティングの仕事がしたいんです。できれば、商品を作るところに関わってみたくて。","en":"I want to work in marketing in the future. If possible, I'd like to be involved in making products."},{"sp":"F","ja":"それなら一つ目ですね。","en":"Then the first one."},{"sp":"M","ja":"ただ、八月の後半はゼミの合宿があって、一週間しか空いていないんです。","en":"But in late August I have a seminar camp, so I only have one week free."},{"sp":"F","ja":"そうですか。食品メーカーは二週間続けて参加することが条件なので、難しいですね。","en":"I see. The food manufacturer requires two consecutive weeks, so that's difficult."},{"sp":"M","ja":"そうですか…。プログラミングはやったことがないし。","en":"Oh... And I've never done programming."},{"sp":"F","ja":"短い期間でも、お客様と直接関わる経験は、マーケティングにも役立ちますよ。お客様が何を求めているかがわかりますから。","en":"Even a short period of dealing directly with customers is useful for marketing. You learn what customers want."},{"sp":"M","ja":"三日間の新聞社もおもしろそうだけど…やっぱり、お客様の声を直接聞けるほうにします。","en":"The three-day newspaper one sounds interesting too, but... I'll go with the one where I can hear customers directly."}],"options":["食品メーカー","旅行会社","IT{企業|きぎょう}","新聞社"],"explain":"The food maker needs two weeks (he has one), IT needs programming; he chooses the one-week travel agency where he serves customers.","answer":1},{"intro":"問題用紙に何も印刷されていません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。\n会社で、課長と女の社員が社員研修について話しています。","question":"研修はどの方法で行うことになりましたか。","lines":[{"sp":"M","ja":"来月の社員研修のやり方だけど、そろそろ決めたいんだ。案は四つあったよね。","en":"About next month's staff training, I'd like to decide soon. There were four proposals, right?"},{"sp":"F","ja":"はい。一つ目は外部の講師を招いて講演をしてもらう方法、二つ目はオンラインの動画教材を各自で見る方法、三つ目は{社員同士|しゃいんどうし}のグループ{討論|とうろん}、四つ目は取引先の工場の見学です。","en":"Yes. One: invite an outside speaker for a lecture. Two: each person watches online video materials. Three: group discussions among staff. Four: a tour of a client's factory."},{"sp":"M","ja":"今回の目的は、部署を越えた{社員同士|しゃいんどうし}のつながりを作ることなんだよね。","en":"The aim this time is to build connections between staff across departments."},{"sp":"F","ja":"それなら、動画教材は一人で見るので合わないですね。講演も、聞くだけになりがちです。","en":"Then video materials, watched alone, don't fit. A lecture also tends to be just listening."},{"sp":"M","ja":"見学はどう？ 移動の間に話もできるし。","en":"How about the tour? People could talk while travelling."},{"sp":"F","ja":"見学は先方の都合で、受け入れが再来月以降になるそうです。","en":"Because of the client's schedule, they can only host us from the month after next."},{"sp":"M","ja":"そうか、それじゃ間に合わないな。じゃあ、残ったのでいこう。テーマは各部署が抱えている課題にしようか。","en":"I see, then it won't be in time. So let's go with the remaining one. Shall we make the theme the issues each department faces?"},{"sp":"F","ja":"はい、わかりました。","en":"Yes, understood."}],"options":["講演","動画教材","グループ{討論|とうろん}","工場見学"],"explain":"Video and lecture don't build connections, and the tour can't happen in time; the remaining option is group discussion.","answer":2},{"intro":"まず話を聞いてください。それから、二つの質問を聞いて、それぞれ問題用紙の1から4の中から、最もよいものを一つ選んでください。\nラジオで、子ども向けのイベントについて紹介しています。それを聞いて、夫婦が話しています。","lines":[{"sp":"N","ja":"今週末、市民ホールで、子どもたちがいろいろな仕事を体験できるイベントが開かれます。プログラムは四つです。一つ目は「パン屋さん」。パン作りを体験し、作ったパンは持ち帰れます。二つ目は「お医者さん」。本物の医療器具に触れながら、{診察|しんさつ}の仕方を学びます。三つ目は「{消防士|しょうぼうし}」。消防服を着て、放水の体験ができます。こちらは屋外で行うため、雨の場合は中止となります。四つ目は「アナウンサー」。ニュースの{原稿|げんこう}を読んで、自分の声を録音します。どのプログラムも小学生が対象ですが、「お医者さん」は四年生以上となっています。なお、{保護者|ほごしゃ}の方は、どのプログラムも見学していただけます。","en":"This weekend at the Civic Hall there's an event where children can try out various jobs. There are four programmes. First, 'Baker': make bread and take it home. Second, 'Doctor': handle real medical instruments and learn how examinations work. Third, 'Firefighter': wear a firefighter's uniform and try spraying water. It's held outdoors, so it will be cancelled if it rains. Fourth, 'Announcer': read a news script and record your own voice. All programmes are for elementary school children, but 'Doctor' is for fourth grade and above. Parents may observe any of the programmes."},{"sp":"M","ja":"うちの健太は二年生だから、お医者さんは無理か。本人は行きたがってたけど。","en":"Our Kenta is in second grade, so Doctor is out. He wanted to do it, though."},{"sp":"F","ja":"そうね。健太は体を動かすのが好きだから、{消防士|しょうぼうし}がいいんじゃない？","en":"Right. Kenta likes moving around, so how about Firefighter?"},{"sp":"M","ja":"でも、週末は雨の予報だよ。","en":"But rain is forecast for the weekend."},{"sp":"F","ja":"あ、そうか。じゃあ、パン屋さんはどう？ 食べるの大好きだし。","en":"Oh, right. Then what about Baker? He loves eating."},{"sp":"M","ja":"いいね、そうしよう。{僕|ぼく}は、参加できるならアナウンサーをやってみたいけどな。","en":"Good, let's do that. If I could take part, I'd want to try Announcer."},{"sp":"F","ja":"子ども向けよ。私は、健太がパンを作ってる間、お医者さんのプログラムを見学してみたいな。病院の事務の仕事をしてるけど、{診察|しんさつ}のことは全然わからないから。","en":"It's for kids. While Kenta makes bread, I'd like to watch the Doctor programme. I work in a hospital office but I know nothing about examinations."},{"sp":"M","ja":"じゃあ、{僕|ぼく}が健太に付いてるよ。","en":"Then I'll stay with Kenta."}],"subq":[{"question":"質問1　二人の子どもは、どのプログラムに参加しますか。","options":["パン屋さん","お医者さん","{消防士|しょうぼうし}","アナウンサー"],"explain":"Doctor is for grade 4+, Firefighter is likely cancelled by rain, so Kenta does Baker.","answer":0},{"question":"質問2　女の人は、どのプログラムを見学したいと言っていますか。","options":["パン屋さん","お医者さん","{消防士|しょうぼうし}","アナウンサー"],"explain":"She wants to observe the Doctor programme because she knows nothing about examinations. The man is the one interested in Announcer.","answer":1}],"question":""}]}]}};